  FrameCardMeta(place: 'theatrum', section: 'casuum-sensus', card: '13', name: 'Quantō differt?', subtitle: 'Cāsūs in nārrātiōne', price: 20, requires: ['theatrum/casuum-sensus/10'], target: 8, lives: 3, lesson: ['Multō ablātīvus mēnsūrae differentiae est. Quantum aetātēs differant indicat; senior comparātiōnem tenet.', 'Paulō mēnsūram parvam differentiae indicat; senior aetātem maiōrem exprimit.', 'Tribus annīs differentiam aetātum mēnsūrat, nōn tempus ante praesēns indicat.', 'Duōbus pedibus excessum altitūdinis mūrī suprā turrim indicat, nōn tōtam altitūdinem.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'casuum-sensus', card: '2', name: 'Pretium et aestimātiō', subtitle: 'Cāsūs in nārrātiōne', price: 20, requires: ['theatrum/casuum-sensus/13'], target: 8, lives: 3, lesson: ['Magnī cum emere pretium magnum significat; nōn cum librum congruit.', 'Parvī genetīvus pretiī est: parvō pretiō. Librum parvum aliam rem dīceret.', 'Plūris pretium maius, nōn numerum librōrum maiōrem indicat.', 'Minōris pretium minus, nōn magnitūdinem librī minōrem indicat.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'casuum-sensus', card: '3', name: 'Quālitās genetīvō expressa', subtitle: 'Cāsūs in nārrātiōne', price: 20, requires: ['theatrum/casuum-sensus/1'], target: 8, lives: 3, lesson: ['Magnae virtūtis quālitātem persōnae exprimit. Genetīvus cum adiectīvō nōn rem possidēndam hīc indicat.', 'Bonī ingeniī quālitātem persōnae exprimit. Genetīvus cum adiectīvō nōn rem possidēndam hīc indicat.', 'Summae sapientiae quālitātem persōnae exprimit. Genetīvus cum adiectīvō nōn rem possidēndam hīc indicat.', 'Magnae cōnstantiae quālitātem persōnae exprimit. Genetīvus cum adiectīvō nōn rem possidēndam hīc indicat.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'casuum-sensus', card: '4', name: 'Possessiō datīvō expressa', subtitle: 'Cāsūs in nārrātiōne', price: 20, requires: [], target: 8, lives: 3, lesson: ['Datīvus cum esse possessōrem indicat: dōnum poētae est idem valet atque poēta dōnum habet.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'casuum-sensus', card: '5', name: 'Datīvus fīnis', subtitle: 'Cāsūs in nārrātiōne', price: 20, requires: ['theatrum/casuum-sensus/2'], target: 8, lives: 3, lesson: ['Auxiliō datīvus fīnis est: cūr veniat ostendit. Auxiliō hīc nōn causam iam effectam indicat.', 'Praesidiō munus protectiōnis indicat; nautae persōnam cui prōdest exprimit.', 'Salūtī datīvus fīnis est: poēta causam salūtis praebuit, nōn ipse hīc salvātus esse dīcitur.', 'Cūrae est rem cūrā dignam indicat. nautae persōnam cūrantem, nōn rem cūrātam, dēsignat.'], examples: []),
