  FrameCardMeta(place: 'theatrum', section: 'casuum-sensus', card: '8', name: 'Quam diū?', subtitle: 'Cāsūs in nārrātiōne', price: 20, requires: ['theatrum/casuum-sensus/6'], target: 8, lives: 3, lesson: ['Trēs diēs quam diū maneat exprimit. Tertiō diē tempus, nōn spatium temporis, indicāret.', 'Duās hōrās spatium temporis accūsātīvō exprimit, nōn tempus certum adventūs.', 'Sex mēnsēs spatium temporis accūsātīvō exprimit, nōn tempus certum adventūs.', 'Duōs annōs spatium temporis accūsātīvō exprimit, nōn tempus certum adventūs.'], examples: []),
