  FrameCardMeta(place: 'theatrum', section: 'formae-non-finitae', card: '1', name: 'Participium coniūnctum', subtitle: 'Fōrmās nōn fīnītās intellegere', price: 20, requires: [], target: 8, lives: 3, lesson: ['Nōminātīvus agentem, accūsātīvus eum ad quem actiō spectat indicat; nōmina nōn permūtanda sunt. Participium praesentis actiōnem eōdem tempore gestam, perfectī actiōnem priōrem, futūrī actiōnem posteram exprimit.', 'Participia perfectī horum verbōrum passīva sunt: subiectum laudātur, vocātur, monētur aut invenītur; nōn ipsum hanc actiōnem agit. Participium praesentis actiōnem eōdem tempore gestam, perfectī actiōnem priōrem, futūrī actiōnem posteram exprimit.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'formae-non-finitae', card: '2', name: 'Gerundīvum', subtitle: 'Fōrmās nōn fīnītās intellegere', price: 20, requires: ['theatrum/formae-non-finitae/1'], target: 8, lives: 3, lesson: ['Gerundīvum attributīvum rem agendam indicat, nōn actiōnem iam perfectam neque agentem futūrum.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'formae-non-finitae', card: '3', name: 'Gerundīvī attractiō', subtitle: 'Fōrmās nōn fīnītās intellegere', price: 20, requires: ['theatrum/formae-non-finitae/2'], target: 8, lives: 3, lesson: ['Fīnis respondet cūr veniat: ad actiōnem agendam venit, nōn post actiōnem perfectam nec eō tempore tantum quō eam agit. Nōmen cum gerundīvō hīc actiōnem verbālem exprimit; nōn dē rē iam perfectā tantum agitur.', 'Nōmen cum gerundīvō hīc actiōnem verbālem exprimit; nōn dē rē iam perfectā tantum agitur.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'formae-non-finitae', card: '4', name: 'Periphrastica actīva', subtitle: 'Fōrmās nōn fīnītās intellegere', price: 20, requires: ['theatrum/formae-non-finitae/3'], target: 8, lives: 3, lesson: ['Participium futūrī actīvī cum esse cōnsilium vel propinquitātem actiōnis exprimit; actiō nōn iam facta affirmātur. Est tempus praesēns, erat tempus praeteritum cōnsiliī vel necessitātis indicat; nōn tempus actiōnis futurae per sē dēfīnit.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'formae-non-finitae', card: '5', name: 'Periphrastica passīva', subtitle: 'Fōrmās nōn fīnītās intellegere', price: 20, requires: ['theatrum/formae-non-finitae/4'], target: 8, lives: 3, lesson: ['Datīvus in hāc periphrasticā passīvā eum indicat cui actiō agenda est. Is nōn necesse est idem ac loquēns esse. Gerundīvum cum esse necessitātem exprimit; participium perfectī cum esse rem factam exprimit. Est tempus praesēns, erat tempus praeteritum cōnsiliī vel necessitātis indicat; nōn tempus actiōnis futurae per sē dēfīnit.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'formae-non-finitae', card: '6', name: 'Supīnum in -um', subtitle: 'Fōrmās nōn fīnītās intellegere', price: 20, requires: ['theatrum/formae-non-finitae/5'], target: 8, lives: 3, lesson: ['Fīnis respondet cūr veniat: ad actiōnem agendam venit, nōn post actiōnem perfectam nec eō tempore tantum quō eam agit. Nōminātīvus agentem, accūsātīvus eum ad quem actiō spectat indicat; nōmina nōn permūtanda sunt.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'formae-non-finitae', card: '7', name: 'Supīnum in -ū', subtitle: 'Fōrmās nōn fīnītās intellegere', price: 20, requires: ['theatrum/formae-non-finitae/6'], target: 8, lives: 3, lesson: ['Facile dictū vel difficile factū rem quoad actiōnem aestimat; neque rem factam neque necessitātem agendī affirmat.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'formae-non-finitae', card: 'vocabula', name: 'Vocābula', subtitle: 'Vocābula sectiōnis: Gallicē', price: 25, requires: ['theatrum/formae-non-finitae/1', 'theatrum/formae-non-finitae/2', 'theatrum/formae-non-finitae/3', 'theatrum/formae-non-finitae/4', 'theatrum/formae-non-finitae/5', 'theatrum/formae-non-finitae/6', 'theatrum/formae-non-finitae/7'], target: 10, lives: 3, lesson: ['Vocābula huius sectiōnis singillātim redde. Utraque via suam perītiam habet.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'gerundium', card: 'gerund-ad', name: 'Ad discendum', subtitle: 'Interpretātiō sententiarum', price: 25, requires: ['theatrum/sententiae/10-sacred'], target: 5, lives: 3, lesson: ['Ad discendum cōnsilium indicat: discere vult is quī venit. Ad accūsātīvum regit: discendum, nōn discendī nec discere. In hīs sententiīs ad cum gerundiō cōnsilium, nōn causam aut sōlum tempus, exprimit.', 'Sententiam tōtam redde. Vocābula hīc explicantur; in extrēmā parte huius sectiōnis probantur.'], examples: ['ad — vers, auprès de ; pour', 'ambulāre — marcher', 'amīcus, amīca — ami, amie', 'cēnāre — dîner', 'discere — apprendre', 'īre — aller', 'exīre — sortir', 'fēmina — femme', 'forum — forum, place publique', 'hortus — jardin', 'in — dans, sur', 'intrāre — entrer', 'lūdere — jouer', 'mercātor — marchand', 'puella — jeune fille', 'puer — garçon', 'schola — école', 'spectāre — regarder', 'theātrum — théâtre', 'vēndere — vendre', 'venīre — venir', 'vīlla — maison de campagne']),
