  FrameCardMeta(place: 'theatrum', section: 'gerundium', card: 'gerund-desire', name: 'Cupidus discendī', subtitle: 'Interpretātiō sententiarum', price: 25, requires: ['theatrum/gerundium/gerund-ad'], target: 5, lives: 3, lesson: ['Cupidus discendī is est quī discere cupit; studiōsus legendī legere valdē amat. Gerundium post haec adiectīva genetīvō pōnitur. Cupiditās actiōnis nōn probat eam iam fierī. Gerundium nōn cum numerō persōnae congruit: puer cupidus discendī, puerī cupidī discendī.', 'Sententiam tōtam redde. Vocābula hīc explicantur; in extrēmā parte huius sectiōnis probantur.'], examples: ['amīcus, amīca — ami, amie', 'cupidus, cupida, cupidum — désireux de', 'discere — apprendre', 'legere — lire', 'lūdere — jouer', 'mercātor — marchand', 'nārrāre — raconter', 'nauta — marin', 'nāvigāre — naviguer', 'puella — jeune fille', 'puer — garçon', 'studiōsus, studiōsa, studiōsum — passionné par', 'esse — être', 'vēndere — vendre']),
