  FrameCardMeta(place: 'theatrum', section: 'itinera', card: 'in-place-motion', name: 'In: ubi an quō?', subtitle: 'Interpretātiō sententiarum', price: 25, requires: ['theatrum/actiones/instrument-agent'], target: 5, lives: 3, lesson: ['In cum ablātīvō locum indicat in quō aliquis est; in cum accūsātīvō locum indicat in quem aliquis intrat. In hortō nōn idem est ac in hortum. Cāsum nōminis et sēnsum verbi simul observā.', 'Sententiam tōtam redde. Vocābula hīc explicantur; in extrēmā parte huius sectiōnis probantur.'], examples: ['ambulāre — marcher', 'cubiculum — chambre', 'currere — courir', 'ex — hors de, depuis', 'fēmina — femme', 'hortus — jardin', 'in — dans, sur', 'magister — maître', 'puella — jeune fille', 'puer — garçon', 'schola — école', 'servus — esclave']),
