  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '1', name: 'Tempus relātum', subtitle: 'Sententiārum nexus', price: 20, requires: [], target: 8, lives: 3, lesson: ['Habitāret eōdem tempore ac rogāvit habitātiōnem pōnit. Habitāvisset antērioritātem indicāret.', 'Rogat praesēns cum faciat praesente coniungitur: actiōnēs eōdem tempore pōnuntur.', 'Fēcisset plusquamperfectum rem priōrem interrogātiōne praeteritā exprimit.', 'Fēcerit perfectum coniūnctīvī rem priōrem interrogātiōne praesente exprimit.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '10', name: 'Quid timētur?', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/9'], target: 8, lives: 3, lesson: ['Post timet nē rem timendam affirmātam intrōdūcit. Nē nōn discessum nōn futūrum timēret.', 'Nē nōn reditum nōn futūrum timendum facit. Hic nē sententiam fīnālem nōn introducit.', 'Post verbum timendī ut idem valet atque nē nōn: absentia adventūs timētur.', 'Nē lēgerit lēctiōnem iam factam timendam pōnit. Nē hīc lēctiōnem nōn negat.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '11', name: 'Quid impeditur?', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/10'], target: 8, lives: 3, lesson: ['Quōminus actiōnem impeditam intrōdūcit: exitus, nōn mora impeditur.', 'Post prohibet nē actiōnem impeditam exprimit. Exitus, nōn mora, impeditur.', 'Quōminus lēctiōnem impeditam exprimit. Datīvus persōnam cui obstat indicat.', 'Nōn impedīmentum negat; quōminus actiōnem nōn impeditam intrōdūcit.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '12', name: 'Quīn post dubitātiōnem negātam', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/11'], target: 8, lives: 3, lesson: ['Nōn dubitat quīn certitūdinem adventūs exprimit. Quīn hīc nōn negātiōnem adventūs addit.', 'Nōn est dubium quīn certitūdinem auxiliī exprimit. Quīn nōn novam negātiōnem actiōnī addit.', 'Nōn dubitāvit dubitātiōnem negat. Adesset praesentiam eō tempore exprimit.', 'Nūlla dubitātiō negātiōnem dubitātiōnis continet; quīn actiōnem nōn negat.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '2', name: 'Quid quaeritur?', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/1'], target: 8, lives: 3, lesson: ['Cūr causam quaerit; interrogātiō post nescit oblīqua est, ideo exeat coniūnctīvus est.', 'Quandō tempus reditūs quaerit, nōn causam nec viam.', 'Quis nōminātīvus persōnam vocantem quaerit; mercātōrem obiectum est.', 'Ubi locum labōris quaerit. Interrogātiō post nescit oblīqua est.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '3', name: 'Effectus, nōn cōnsilium', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/2'], target: 8, lives: 3, lesson: ['Tam … ut effectum exprimit. Laus ex fortitūdine sequitur; cōnsilium pugnantis nōn affirmātur.', 'Ita … ut effectum sermōnis indicat; nōn cōnsilium fraudandī affirmat.', 'Tantā vōce … ut effectum magnitūdinis vōcis exprimit.', 'Adeō … ut nōn effectum negātum exprimit. Sententia fīnālis negāta nē haberet.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '4', name: 'Quamvīs et tamen', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/3'], target: 8, lives: 3, lesson: ['Quamvīs rem admissam, tamen contrārium exspectātiōnī indicat. Causa vel cōnsilium nōn exprimitur.', 'Quamquam paupertātem ut rem certam admittit; tamen dōnum contrā exspectātiōnem addit.', 'Etsī rem etiam admissam cōnsiliō vel causae nōn aequat; tamen concessiōnem confirmat.', 'Tametsī absentiam admittit, sed laudem nōn impeditam esse ostendit.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '5', name: 'Dum et simul', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/4'], target: 8, lives: 3, lesson: ['Dum cum praesente hīc duās actiōnēs simul factās coniungit.', 'Postquam adventum priōrem apertūrā portae facit.', 'Antequam responsum post discessum pōnit; nōn responsum iam datum nārrat.', 'Dōnec adventum terminum morae facit; mora adventum antecedit et ad eum pertinet.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '6', name: 'Cum in nārrātiōne', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/5'], target: 8, lives: 3, lesson: ['Cum manēret statum dūrantem praebet in quō adventus accidit. Perfectum vēnit adventum, imperfectum manēret statum exprimit.', 'Scrīpsisset rem ante vocāvit perfectam exprimit; scrīberet rem simul factam indicāret.', 'Dormīret somnum apertūrā portae dūrantem exprimit.', 'Advēnisset adventum ante initium labōris iam perfectum pōnit.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '7', name: 'Causa nārrāta', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/6'], target: 8, lives: 3, lesson: ['Quod causam discessūs exprimit; vocāverat vocātiōnem priōrem discessū facit.', 'Quia praesentiam causam gaudiī facit, nōn cōnsilium futūrum.', 'Quoniam causam ut rem nōtam intrōdūcit.', 'Idcircō nexum causae confirmat. Cum absit hīc causāle est, nōn sōlum tempus indicat.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '8', name: 'Quī cōnsilium indicat', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/7'], target: 8, lives: 3, lesson: ['Quī petat relātīva cōnsiliī est: quō cōnsiliō mittātur ostendit, nōn rem iam factam nārrat.', 'Quī portet cōnsilium missiōnis exprimit, nōn factum iam perfectum.', 'Quī aperiant cōnsilium exprimit; aperiant plūrāle cum antecēdente plūrālī congruit.', 'Quī quaereret fīnem missiōnis praeteritae exprimit.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'nexus-sententiarum', card: '9', name: 'Quālis sit', subtitle: 'Sententiārum nexus', price: 20, requires: ['theatrum/nexus-sententiarum/8'], target: 8, lives: 3, lesson: ['Nōn is est quī … proprietātem persōnae negat. Dēserat coniūnctīvus quālis sit exprimit.', 'Nōn is est quī … indolem negat; nōn actiōnem singulam praeteritam nec iussum nārrat.'], examples: []),
