  FrameCardMeta(place: 'theatrum', section: 'nomina', card: 'third-ablative', name: 'Cum mātre, cum patre', subtitle: 'Interpretātiō sententiarum', price: 20, requires: ['theatrum/nomina/third-dative'], target: 5, lives: 3, lesson: ['Cum et sine ablātīvum regunt. In hīs nōminibus tertiae dēclīnātiōnis ablātīvus singulāris in -e dēsinit: mātre, patre, frātre, sorōre, pāstōre, cane. Cum mātre comitem indicat; sine mātre comitem abesse indicat. Ad mātrem fīnem mōtūs indicat.', 'Sententiam tōtam redde. Vocābula hīc explicantur; in extrēmā parte huius sectiōnis probantur.'], examples: ['agricola — agriculteur', 'ambulāre — marcher', 'canis — chien', 'cum — avec', 'currere — courir', 'frāter — frère', 'māter — mère', 'pāstor — berger', 'pater — père', 'puella — jeune fille', 'puer — garçon', 'redīre — revenir', 'sine — sans', 'soror — sœur', 'venīre — venir']),
