  FrameCardMeta(place: 'theatrum', section: 'numerorum-sensus', card: 'vocabula', name: 'Vocābula', subtitle: 'Vocābula sectiōnis: Gallicē', price: 25, requires: ['theatrum/numerorum-sensus/1', 'theatrum/numerorum-sensus/2', 'theatrum/numerorum-sensus/3', 'theatrum/numerorum-sensus/4'], target: 10, lives: 3, lesson: ['Vocābula huius sectiōnis singillātim redde. Utraque via suam perītiam habet.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'oratio-obliqua', card: '1', name: 'Accūsātīvus cum īnfīnītīvō', subtitle: 'Ōrātiōnem oblīquam intellegere', price: 20, requires: [], target: 8, lives: 3, lesson: ['Īnfīnītīvus perfectī rem ante verbum dīcendī factam exprimit; praesēns rem eōdem tempore, futūrus rem posteriōrem exprimeret.', 'Post verbum praeteritum īnfīnītīvus futūrī rem posteā futūram, nōn rem iam anteā factam indicat.', 'Subiectum verbī dīcendī loquitur; subiectum īnfīnītīvī rem relātam agit. Haec subiecta distinguenda sunt.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'oratio-obliqua', card: '2', name: 'Nōminātīvus cum īnfīnītīvō', subtitle: 'Ōrātiōnem oblīquam intellegere', price: 20, requires: ['theatrum/oratio-obliqua/1'], target: 8, lives: 3, lesson: ['In cōnstrūctiōne dīcitur cum īnfīnītīvō aliī rem dē subiectō referunt; subiectum nōn ipsum loquī affirmātur.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'oratio-obliqua', card: '3', name: 'Iussa oblīqua', subtitle: 'Ōrātiōnem oblīquam intellegere', price: 20, requires: ['theatrum/oratio-obliqua/2'], target: 8, lives: 3, lesson: ['Nē in iussō oblīquō rem prohibet; ut sine negātiōne rem agendam iubet. Imperat ut vel nē iussum exprimit; rem factam affirmāre et aliquid imperāre nōn idem sunt.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'oratio-obliqua', card: '4', name: 'Interrogātiōnēs in nārrātiōne', subtitle: 'Ōrātiōnem oblīquam intellegere', price: 20, requires: ['theatrum/oratio-obliqua/3'], target: 8, lives: 3, lesson: ['Plusquamperfectum coniūnctīvī rem ante interrogātiōnem praeteritam factam exprimit; imperfectum rem eōdem tempore indicāret.'], examples: []),
  FrameCardMeta(place: 'theatrum', section: 'oratio-obliqua', card: '5', name: 'Prōnōmina et loquēns', subtitle: 'Ōrātiōnem oblīquam intellegere', price: 20, requires: ['theatrum/oratio-obliqua/4'], target: 8, lives: 3, lesson: ['Sē in hāc ōrātiōne oblīquā ad eum quī loquitur refertur; eum alium virum indicat.', 'Suus in hīs verbīs ad loquentem refertur; eius alterīus possessiōnem indicat. Possessor ē contextū reperiendus est.'], examples: []),
