  FrameCardMeta(place: 'theatrum', section: 'orationes', card: 'infinitive-anteriority', name: 'Cantāre et cantāvisse', subtitle: 'Interpretātiō sententiarum', price: 25, requires: ['theatrum/orationes/infinitive-subject'], target: 5, lives: 3, lesson: ['Īnfīnītīvus praesēns actiōnem cum verbō regente simul fierī indicat; īnfīnītīvus perfectus eam anteā factam esse indicat. Dīcit puerum cantāre: puer nunc cantat. Dīcit puerum cantāvisse: puer anteā cantāvit. Tempus īnfīnītīvī ad tempus verbi regentis refertur.', 'Sententiam tōtam redde. Vocābula hīc explicantur; in extrēmā parte huius sectiōnis probantur.'], examples: ['agricola — agriculteur', 'aperīre — ouvrir', 'cantāre — chanter', 'dīcere — dire', 'dominus — maître de maison', 'dormīre — dormir', 'epistula — lettre envoyée', 'fēmina — femme', 'fīlius — fils', 'legere — lire', 'liber — livre', 'magister — maître', 'mercātor — marchand', 'pater — père', 'porta — porte d’une ville', 'puella — jeune fille', 'puer — garçon', 'scrībere — écrire', 'servus — esclave', 'venīre — venir']),
