  FrameCardMeta(place: 'theatrum', section: 'sententiae', card: '07-purpose', name: 'Ut et nē', subtitle: 'Interpretātiō sententiarum', price: 25, requires: ['theatrum/orationes/past-posteriority'], target: 5, lives: 3, lesson: ['In hīs sententiīs ut cum subiūnctīvō cōnsilium indicat; nē cōnsilium negātīvum indicat. Puer currit ut aquam petat: aquam petere vult. Puella tacet nē puerum excitet: puerum excitāre nōn vult. Quia causam indicat, nōn cōnsilium. Hīc verba prīncipālia praesentia sunt et in cōnsiliīs subiūnctīvus praesēns adhibētur. Cōnsilia temporis praeteritī aliīs fōrmīs exprimuntur.', 'Sententiam tōtam redde. Vocābula in extrēmā parte huius sectiōnis probantur.'], examples: ['ad — vers, auprès de', 'aqua — eau', 'cadere — tomber', 'claudere — fermer', 'currere — courir', 'discēdere — s’en aller', 'excitāre — réveiller', 'fēmina — femme', 'flūmen — fleuve', 'frīgus — froid', 'iānua — porte', 'in — dans, sur', 'intrāre — entrer', 'nauta — marin', 'nāvis — navire', 'nē — pour que… ne… pas', 'nōn — ne… pas', 'oppidum — ville fortifiée', 'parāre — préparer', 'pater — père', 'pervenīre — parvenir, arriver', 'petere — chercher à obtenir, demander', 'puella — jeune fille', 'puer — garçon', 'quaerere — chercher, demander', 'quia — parce que', 'tacēre — se taire', 'tenēre — tenir', 'ut — pour que', 'vēlum — voile de bateau', 'via — route', 'viātor — voyageur']),
  FrameCardMeta(place: 'theatrum', section: 'sententiae', card: '08-circumstances', name: 'Puerō cantante', subtitle: 'Ablātīvus absolūtus', price: 25, requires: ['theatrum/sententiae/purpose-past'], target: 5, lives: 3, lesson: ['Puerō cantante, māter epistulam scrībit: puer cantat, māter scrībit. Puerō et cantante ablātīvī sunt; māter subiectum verbī scrībit est. Hīc participium praesēns actiōnem eōdem tempore factam indicat. Puer cantāns epistulam scrībit aliam rem significat: puer ipse scrībit. Antequam autem actiōnem nōndum factam indicat. Ablātīvus absolūtus aliōs quoque sēnsūs habēre potest; hīc duās actiōnēs simul factās distinguimus.', 'Sententiam tōtam redde. Vocābula in extrēmā parte huius sectiōnis probantur.'], examples: ['ambulāre — marcher', 'amīcus, amīca — ami, amie', 'antequam — avant que', 'aperīre — ouvrir', 'aqua — eau', 'cantāre — chanter', 'carpere — cueillir', 'cēna — dîner', 'clāmāre — crier', 'epistula — lettre envoyée', 'fēmina — femme', 'iānua — porte', 'labōrāre — travailler', 'māter — mère', 'mercātor — marchand', 'nārrāre — raconter', 'nauta — marin', 'parāre — préparer', 'portāre — porter', 'puella — jeune fille', 'puer — garçon', 'rosa — rose', 'scrībere — écrire', 'servus — esclave', 'vēlum — voile de bateau', 'venīre — venir, arriver', 'viātor — voyageur']),
