  FrameCardMeta(place: 'theatrum', section: 'sermo', card: 'eos-eas', name: 'Eōs et eās', subtitle: 'Interpretātiō sententiarum', price: 20, requires: ['theatrum/sermo/eum-eam'], target: 3, lives: 3, lesson: ['Eōs et eās accūsātīvī plūrālēs sunt. Eōs ad nōmina masculīna, eās ad nōmina fēminīna referuntur. Eum vel eam ūnum, eōs vel eās plūrēs significant. Genus et numerum antecedentis simul servā.', 'Sententiam tōtam redde. Vocābula hīc explicantur; in extrēmā parte huius sectiōnis probantur.'], examples: ['adesse — être présent', 'audīre — entendre, apprendre une nouvelle', 'fēmina — femme', 'hortus — jardin', 'in — dans, sur', 'is, ea, id — celui-ci, celle-ci, cela', 'liber — livre', 'magister — maître', 'portāre — porter', 'puella — jeune fille', 'puer — garçon', 'rosa — rose', 'schola — école', 'esse — être', 'vidēre — voir', 'vocāre — appeler']),
