  FrameCardMeta(place: 'templum', section: 'casuum-electio', card: '4', name: 'Possessōrem datīvō pōnere', subtitle: 'Cāsibus sententiam compōnere', price: 20, requires: [], target: 8, lives: 3, lesson: ['Mihi datīvus possessōris est. In ōrātiōne rēctā loquēns sē prīmā persōnā dēsignat.', 'Tibi datīvus possessōrem secundā persōnā singulārī exprimit.', 'Nōbīs datīvus possessōrem prīmā persōnā plūrālī exprimit. Liber manet subiectum singulāre.', 'Vōbīs datīvus possessōrem secundā persōnā plūrālī exprimit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'casuum-electio', card: '5', name: 'Fīnem datīvō indicāre', subtitle: 'Cāsibus sententiam compōnere', price: 20, requires: ['templum/casuum-electio/4'], target: 8, lives: 3, lesson: ['Auxiliō datīvus fīnis est: cūr mittātur indicat.', 'Praesidiō datīvus fīnis est: quō mūnere fungantur exprimit.', 'Salūtī datīvus fīnis cum fuit coniungitur. Persōna cui prōfuit alterō datīvō exprimitur.', 'Cūrae est significat cūram movet. Cūrā ablātīvus causam, nōn hoc munus, exprimeret.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'casuum-electio', card: '6', name: 'Duōs datīvōs coniungere', subtitle: 'Cāsibus sententiam compōnere', price: 20, requires: ['templum/casuum-electio/5'], target: 8, lives: 3, lesson: ['Datīvus persōnae cum praesidiō datīvō fīnis coniungitur.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'casuum-electio', card: '7', name: 'Spatium accūsātīvō pōnere', subtitle: 'Cāsibus sententiam compōnere', price: 20, requires: ['templum/casuum-electio/8'], target: 8, lives: 3, lesson: ['Mēnsūra altitūdinis accūsātīvō exprimitur: trīgintā pedēs alta.', 'Mēnsūra altitūdinis accūsātīvō exprimitur: vīgintī cubitōs altus.', 'Centum pedēs accūsātīvus longitudinem nāvis exprimit; longa cum nāvis congruit.', 'Duo mīlia accūsātīvus lātitūdinem exprimit; passuum genetīvus ūnitātem mēnsūrae addit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'casuum-electio', card: '8', name: 'Spatium temporis compōnere', subtitle: 'Cāsibus sententiam compōnere', price: 20, requires: ['templum/casuum-electio/6'], target: 8, lives: 3, lesson: ['Duās hōrās accūsātīvus spatium temporis indicat. Secundā hōrā aliud significat.', 'Trēs diēs accūsātīvus dūrātiōnem exspectātiōnis exprimit.', 'Sex mēnsēs accūsātīvus dūrātiōnem exspectātiōnis exprimit.', 'Ūnum annum accūsātīvus dūrātiōnem exspectātiōnis exprimit.'], examples: []),
