  FrameCardMeta(place: 'templum', section: 'formis-non-finitis', card: '1', name: 'Participium coniūnctum', subtitle: 'Fōrmīs nōn fīnītīs ūtī', price: 20, requires: [], target: 8, lives: 3, lesson: ['Participium ad subiectum huius sententiae pertinet et nōminātīvum postulat. Cāsus oblīquus aliud nōmen indicāret. Participium praesentis actiōnem eōdem tempore gestam, perfectī actiōnem priōrem, futūrī actiōnem posteram exprimit.', 'Participium ad subiectum huius sententiae pertinet et nōminātīvum postulat. Cāsus oblīquus aliud nōmen indicāret. Participia perfectī horum verbōrum passīva sunt: subiectum laudātur, vocātur, monētur aut invenītur; nōn ipsum hanc actiōnem agit. Participium praesentis actiōnem eōdem tempore gestam, perfectī actiōnem priōrem, futūrī actiōnem posteram exprimit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'formis-non-finitis', card: '2', name: 'Gerundīvum', subtitle: 'Fōrmīs nōn fīnītīs ūtī', price: 20, requires: ['templum/formis-non-finitis/1'], target: 8, lives: 3, lesson: ['Gerundīvum eōdem genere ac nōmen suum ponitur: liber legendus, epistula scrībenda, carmen cantandum.', 'Gerundīvum eōdem genere ac nōmen suum ponitur: liber legendus, epistula scrībenda, carmen cantandum. Nōmen plūrāle gerundīvum plūrāle postulat: librī legendī, epistulae scrībendae, dōna portanda.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'formis-non-finitis', card: '3', name: 'Gerundīvī attractiō', subtitle: 'Fōrmīs nōn fīnītīs ūtī', price: 20, requires: ['templum/formis-non-finitis/2'], target: 8, lives: 3, lesson: ['Post ad nōmen et gerundīvum in accūsātīvō ponuntur; gerundīvum etiam genere et numerō congruit. Gerundīvum eōdem genere ac nōmen suum ponitur: liber legendus, epistula scrībenda, carmen cantandum.', 'Causā postpositum genitīvum postulat: librōrum legendōrum causā. Utraque fōrma eundem cāsum servat.', 'In hāc cōnstrūctiōne in cum ablātīvō actiōnem significat: in librīs legendīs. Nōmen et gerundīvum in ablātīvō sunt.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'formis-non-finitis', card: '4', name: 'Periphrastica actīva', subtitle: 'Fōrmīs nōn fīnītīs ūtī', price: 20, requires: ['templum/formis-non-finitis/3'], target: 8, lives: 3, lesson: ['Participium futūrī actīvī cum esse cōnsilium vel propinquitātem actiōnis exprimit; actiō nōn iam facta affirmātur. Est tempus praesēns, erat tempus praeteritum cōnsiliī vel necessitātis indicat; nōn tempus actiōnis futurae per sē dēfīnit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'formis-non-finitis', card: '5', name: 'Periphrastica passīva', subtitle: 'Fōrmīs nōn fīnītīs ūtī', price: 20, requires: ['templum/formis-non-finitis/4'], target: 8, lives: 3, lesson: ['Datīvus in hāc periphrasticā passīvā eum indicat cui actiō agenda est. Is nōn necesse est idem ac loquēns esse. Gerundīvum cum esse necessitātem exprimit; participium perfectī cum esse rem factam exprimit. Est tempus praesēns, erat tempus praeteritum cōnsiliī vel necessitātis indicat; nōn tempus actiōnis futurae per sē dēfīnit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'formis-non-finitis', card: '6', name: 'Supīnum in -um', subtitle: 'Fōrmīs nōn fīnītīs ūtī', price: 20, requires: ['templum/formis-non-finitis/5'], target: 8, lives: 3, lesson: ['Post verbum veniendī supīnum in -um fīnem exprimit. Supīnum in -ū cum adiectīvīs ut facile vel difficile iungitur. Fīnis respondet cūr veniat: ad actiōnem agendam venit, nōn post actiōnem perfectam nec eō tempore tantum quō eam agit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'formis-non-finitis', card: '7', name: 'Supīnum in -ū', subtitle: 'Fōrmīs nōn fīnītīs ūtī', price: 20, requires: ['templum/formis-non-finitis/6'], target: 8, lives: 3, lesson: ['Facile dictū vel difficile factū rem quoad actiōnem aestimat; neque rem factam neque necessitātem agendī affirmat.'], examples: []),
