  FrameCardMeta(place: 'templum', section: 'orationem-referre', card: '1', name: 'Accūsātīvus cum īnfīnītīvō', subtitle: 'Ōrātiōnem referre', price: 20, requires: [], target: 8, lives: 3, lesson: ['Īnfīnītīvus perfectī rem ante verbum dīcendī factam exprimit; praesēns rem eōdem tempore, futūrus rem posteriōrem exprimeret.', 'Post verbum praeteritum īnfīnītīvus futūrī rem posteā futūram, nōn rem iam anteā factam indicat.', 'Subiectum accūsātīvī cum īnfīnītīvō in accūsātīvō ponitur, quamquam subiectum sententiae rēctae nōminātīvum habet.'], examples: []),
