  FrameCardMeta(place: 'templum', section: 'pronomina-eligenda', card: '1', name: 'Indēfīnīta', subtitle: 'Prōnōmina ēligere', price: 20, requires: [], target: 8, lives: 3, lesson: ['Post sī, quis hominem indēfīnītum potest dēsignāre.', 'Nēmō negātiōnem continet: nūllus homō videt.', 'Nōn quidquam idem valet ac nihil: nūlla rēs dīcitur.', 'Quīvīs līberam ēlectiōnem exprimit: quīcumque vult.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'pronomina-eligenda', card: '2', name: 'Interrogātīva', subtitle: 'Prōnōmina ēligere', price: 20, requires: ['templum/pronomina-eligenda/1'], target: 8, lives: 3, lesson: ['Quid rem quaesītam interrogat, nōn hominem nec accipientem.', 'Cuius genitīvus possessōrem librī interrogat.', 'Cum sociātīvum ablātīvum quō postulat.', 'Uter hominem ē duōbus ēligendum interrogat.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'pronomina-eligenda', card: '3', name: 'Relātīva indēfīnīta', subtitle: 'Prōnōmina ēligere', price: 20, requires: ['templum/pronomina-eligenda/2'], target: 8, lives: 3, lesson: ['Quīcumque omnem venientem sine exceptiōne significat.', 'Quidquid rēs scrīptās ūniversās complectitur.', 'Quāliscumque qualitatem hominis apertam relinquit.', 'Quisquis omnēs audientēs comprehendit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'pronomina-eligenda', card: '4', name: 'Ipse et īdem', subtitle: 'Prōnōmina ēligere', price: 20, requires: ['templum/pronomina-eligenda/3'], target: 8, lives: 3, lesson: ['Ipse praesentiam agentis auget; īdem identitātem repetītam significat.', 'Eundem ad librum iam dictum refertur.', 'Ipsī datīvus accipientem in persōnā auget.', 'Īdem eundem hominem inter tempora coniungit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'pronomina-eligenda', card: 'vocabula', name: 'Vocābula', subtitle: 'Vocābula sectiōnis: Latīnē', price: 25, requires: ['templum/pronomina-eligenda/1', 'templum/pronomina-eligenda/2', 'templum/pronomina-eligenda/3', 'templum/pronomina-eligenda/4'], target: 10, lives: 3, lesson: ['Vocābula huius sectiōnis singillātim redde. Utraque via suam perītiam habet.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '1', name: 'Tempora inter sē accommodāre', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/2'], target: 8, lives: 3, lesson: ['Post rogāvit actiō eōdem tempore facta imperfectō coniūnctīvī exprimitur: faceret. Fēcisset antērioritātem indicāret.', 'Post quaerit scrībat actiōnem praesentem eōdem tempore exprimit.', 'Scrīpserit actiōnem ante quaerit iam perfectam exprimit.', 'Scrīpsisset actiōnem ante interrogātiōnem praeteritam iam perfectam exprimit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '10', name: 'Rem timendam negāre', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/9'], target: 8, lives: 3, lesson: ['Nē nōn rem nōn futūram timendam facit. Sōlum nē adventum ipsum timendum faceret.', 'Nē adventum ipsum timendum facit; nē nōn adventum nōn futūrum timēret.', 'Ut post timet idem valet atque nē nōn; postquam aliud tempus, nōn hunc timōrem, exprimeret.', 'Nē lēctiōnem iam factam timendam facit. Negātiō nōn ad lēctionem transfertur.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '11', name: 'Actiōnem impeditam subiungere', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/10'], target: 8, lives: 3, lesson: ['Quōminus actiōnem impeditam intrōdūcit. Postquam tempus, quamvīs concessiōnem exprimeret.', 'Nē post prohibet actiōnem vetitam intrōdūcit.', 'Quōminus lēctiōnem cui obstat intrōdūcit.', 'Post nōn impedit quīn licet: actiōnem nōn impeditam intrōdūcit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '12', name: 'Dubitātiōnem negāre', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/11'], target: 8, lives: 3, lesson: ['Post nōn dubitat quīn sententiam cui fīdēs habētur intrōdūcit. Nē cum timōre, quōminus cum impedīmentō coniungitur.', 'Quīn post dubium negātum sententiam certam intrōdūcit.', 'Quīn post nōn dubitāvit ponitur; adesset cōnsecūtiōnem historicam servat.', 'Nūlla dubitātiō negātiōnem praebet quae quīn admittit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '2', name: 'Interrogātiōnem subiungere', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/5'], target: 8, lives: 3, lesson: ['Post dīc interrogātiō oblīqua de rē praesente coniūnctīvum praesentem habet: maneat. Mānserit rem priōrem indicāret.', 'Quandō tempus quaerit; cūr causam, quis persōnam quaereret.', 'Ubi locum quaerit. Labōret in interrogātiōne oblīquā coniūnctīvus est.', 'Quis subiectum vocet est. Quem obiectum alterum faceret, cui accipientem indicāret.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '3', name: 'Effectum subiungere', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/6'], target: 8, lives: 3, lesson: ['Effectus praesēns post tam fessus est coniūnctīvō praesente exprimitur: possit.', 'Ita … ut effectum exprimit. Nihil negātiōnem effectūs continet.', 'Posset effectum eōdem tempore ac erat exprimit; potuisset antērioritātem dīceret.', 'In consecutīvā ut nōn ponitur. Nē fīnem negātum intrōdūceret; nihil cum eum obiectum mutāret.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '4', name: 'Concessiōnem subiungere', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/3'], target: 8, lives: 3, lesson: ['Quamvīs concessīvum cum coniūnctīvō hīc ponitur. Sit statum praesentem exprimit, nōn praeteritum ante aliud praeteritum.', 'Tamen contrārium exspectātiōnī post concessiōnem signat; itaque effectum causae significāret.', 'Esset statum praeteritum eōdem tempore ac agēbat exprimit.', 'Tametsī cum tamen concessiōnem facit. Quia causam, ut aliud genus subōrdinātiōnis faceret.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '5', name: 'Ordinem factōrum compōnere', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/7'], target: 8, lives: 3, lesson: ['Postquam adventum priōrem discessū facit. Priusquam ordinem inverteret; dum simultāneitātem exprimeret.', 'Dum simultāneitātem, nōn actiōnem priōrem aut posteriōrem exprimit.', 'Antequam responsum post discessum pōnit.', 'Dōnec terminum morae indicat. Postquam ordinem inverteret; quamquam concessiōnem adderet.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '6', name: 'Statum nārrātiōnis compōnere', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/1'], target: 8, lives: 3, lesson: ['In nārrātiōne cum scrīberet actiōnem legēbat simul comitātam exprimit. Scrīpsisset scrīptūram iam perfectam pōneret.', 'Scrīpsisset scrīptūram priōrem lēctiōne exprimit.', 'Dormīret statum dūrantem eōdem tempore ac aperuit exprimit.', 'Advēnisset adventum iam perfectum ante initium labōris exprimit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '7', name: 'Causam subiungere', subtitle: 'Sententiās subiungere', price: 20, requires: [], target: 8, lives: 3, lesson: ['Quod causam indicat. Ut cōnsilium vel effectum, quamvīs concessiōnem introduceret.', 'Quoniam causam intrōdūcit, nōn concessiōnem vel fīnem.', 'Quia causam gaudiī exprimit. Indicātīvus adest praesentiam affirmat.', 'Cum causāle coniūnctīvum habet. Absit causam praesentem, nōn priōrem statum praeteritum exprimit.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '8', name: 'Relātīvā cōnsilium exprimere', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/4'], target: 8, lives: 3, lesson: ['Quī ferat cōnsilium futūrum post iussum mittite exprimit. Tulerit vel tulisset rem iam factam indicāret.', 'Peteret coniūnctīvus imperfectus cōnsilium post mīsit exprimit. Petēbat factum nārrāret; petat cōnsecūtiōnem primāriam haberet.', 'Petant coniūnctīvus praesēns plūrālis est: cōnsilium, tempus prīmārium et numerum antecēdentis servat.', 'Portet coniūnctīvus cōnsilium exprimit; portat vel portābat factum indicātīvō nārrārent.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: '9', name: 'Proprietātem relātīvā exprimere', subtitle: 'Sententiās subiungere', price: 20, requires: ['templum/sententiae-subordinatae/8'], target: 8, lives: 3, lesson: ['Nēmō est quī … proprietātem generālem exprimit. Sit cum parātus statum praesentem dēsignat.', 'Coniūnctīvus praesēns indolem persōnae exprimit. Indicātīvus factum certum, perfectum rem priōrem dīceret.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae-subordinatae', card: 'vocabula', name: 'Vocābula', subtitle: 'Vocābula sectiōnis: Latīnē', price: 25, requires: ['templum/sententiae-subordinatae/7', 'templum/sententiae-subordinatae/5', 'templum/sententiae-subordinatae/2', 'templum/sententiae-subordinatae/1', 'templum/sententiae-subordinatae/6', 'templum/sententiae-subordinatae/3', 'templum/sententiae-subordinatae/4', 'templum/sententiae-subordinatae/8', 'templum/sententiae-subordinatae/9', 'templum/sententiae-subordinatae/10', 'templum/sententiae-subordinatae/11', 'templum/sententiae-subordinatae/12'], target: 10, lives: 3, lesson: ['Vocābula huius sectiōnis singillātim redde. Utraque via suam perītiam habet.'], examples: []),
  FrameCardMeta(place: 'templum', section: 'sententiae', card: '07-purpose', name: 'Ut et nē', subtitle: 'Compositiō sententiarum', price: 25, requires: ['templum/orationes/past-posteriority'], target: 5, lives: 3, lesson: ['In hīs sententiīs ut cum subiūnctīvō cōnsilium indicat; nē cōnsilium negātīvum indicat. Puer currit ut aquam petat: aquam petere vult. Puella tacet nē puerum excitet: puerum excitāre nōn vult. Quia causam indicat, nōn cōnsilium. Hīc verba prīncipālia praesentia sunt et in cōnsiliīs subiūnctīvus praesēns adhibētur. Cōnsilia temporis praeteritī aliīs fōrmīs exprimuntur.', 'Sententiam tōtam redde. Vocābula in extrēmā parte huius sectiōnis probantur.'], examples: ['ad — vers, auprès de', 'aqua — eau', 'cadere — tomber', 'claudere — fermer', 'currere — courir', 'discēdere — s’en aller', 'excitāre — réveiller', 'fēmina — femme', 'flūmen — fleuve', 'frīgus — froid', 'iānua — porte', 'in — dans, sur', 'intrāre — entrer', 'nauta — marin', 'nāvis — navire', 'nē — pour que… ne… pas', 'nōn — ne… pas', 'oppidum — ville fortifiée', 'parāre — préparer', 'pater — père', 'pervenīre — parvenir, arriver', 'petere — chercher à obtenir, demander', 'puella — jeune fille', 'puer — garçon', 'quaerere — chercher, demander', 'quia — parce que', 'tacēre — se taire', 'tenēre — tenir', 'ut — pour que', 'vēlum — voile de bateau', 'via — route', 'viātor — voyageur']),
  FrameCardMeta(place: 'templum', section: 'sententiae', card: '08-circumstances', name: 'Puerō cantante', subtitle: 'Ablātīvus absolūtus', price: 25, requires: ['templum/sententiae/purpose-past'], target: 5, lives: 3, lesson: ['Puerō cantante, māter epistulam scrībit: puer cantat, māter scrībit. Puerō et cantante ablātīvī sunt; māter subiectum verbī scrībit est. Hīc participium praesēns actiōnem eōdem tempore factam indicat. Puer cantāns epistulam scrībit aliam rem significat: puer ipse scrībit. Antequam autem actiōnem nōndum factam indicat. Ablātīvus absolūtus aliōs quoque sēnsūs habēre potest; hīc duās actiōnēs simul factās distinguimus.', 'Sententiam tōtam redde. Vocābula in extrēmā parte huius sectiōnis probantur.'], examples: ['ambulāre — marcher', 'amīcus, amīca — ami, amie', 'antequam — avant que', 'aperīre — ouvrir', 'aqua — eau', 'cantāre — chanter', 'carpere — cueillir', 'cēna — dîner', 'clāmāre — crier', 'epistula — lettre envoyée', 'fēmina — femme', 'iānua — porte', 'labōrāre — travailler', 'māter — mère', 'mercātor — marchand', 'nārrāre — raconter', 'nauta — marin', 'parāre — préparer', 'portāre — porter', 'puella — jeune fille', 'puer — garçon', 'rosa — rose', 'scrībere — écrire', 'servus — esclave', 'vēlum — voile de bateau', 'venīre — venir, arriver', 'viātor — voyageur']),
  FrameCardMeta(place: 'templum', section: 'sententiae', card: '10-sacred', name: 'Causae et cōnsilia', subtitle: 'Compositiō sententiarum', price: 25, requires: ['templum/sententiae/absolute-perfect'], target: 3, lives: 3, lesson: ['Cōnsilium persōnae, factum et quod ex factō sequitur distingue. Volēbat cōnsilium, partīta est factum, audīverant rem anteā cognitam indicat. Ex verbīs sententiae responde, nōn ex rēbus quas ipse addis.', 'Sententiam tōtam redde. Fōrmās et litterās longās dīligenter observā. Vocābula hīc explicantur; in extrēmā parte huius sectiōnis probantur.'], examples: ['vidua — veuve', 'pānis — pain', 'fīlius — fils', 'servāre — garder', 'velle — vouloir', 'cum — avec', 'peregrīnus — étranger, voyageur', 'partīrī — partager', 'esse — être', 'vīcīnus — voisin', 'rēs — chose, événement', 'audīre — entendre, apprendre une nouvelle', 'misericordia — compassion', 'etiam — même, aussi', 'in — dans, sur', 'inopia — manque, pauvreté', 'exercēre — exercer', 'posse — pouvoir', 'dare — donner', 'nōlle — ne pas vouloir', 'sōlus — seul', 'habēre — avoir', 'ā — de, depuis ; par', 'auferre — emporter, enlever', 'tantum — seulement', 'dīvitiae — richesses', 'nōn — ne… pas']),
  FrameCardMeta(place: 'templum', section: 'sententiae', card: 'absolute-perfect', name: 'Epistulā lēctā', subtitle: 'Ablātīvus absolūtus', price: 25, requires: ['templum/sententiae/08-circumstances'], target: 5, lives: 3, lesson: ['Epistulā lēctā, pater fīlium vocat: epistula iam lēcta est cum pater vocat. Nōn dīcitur quis epistulam lēgerit. Epistulā et lēctā ablātīvī sunt. Participium perfectum hīc rem iam factam vel statum inde ortum indicat. Puerīs perterritīs puerōs iam perterritōs esse indicat; nōn dīcit puerōs alium perterrēre. Dum rēs fit et antequam fit aliōs temporum ōrdinēs indicant.', 'Sententiam tōtam redde. Vocābula in extrēmā parte huius sectiōnis probantur.'], examples: ['amīcus, amīca — ami, amie', 'antequam — avant que', 'aperīre — ouvrir', 'cēna — dîner', 'cīvis — citoyen', 'claudere — fermer', 'dēlēre — détruire, effacer', 'discipulus — élève', 'dum — pendant que', 'epistula — lettre envoyée', 'exīre — sortir', 'fīlius — fils', 'fugere — s’enfuir', 'iānua — porte', 'intrāre — entrer', 'legere — lire', 'liber — livre', 'māter — mère', 'oppidum — ville fortifiée', 'parāre — préparer', 'pater — père', 'perterrēre — terrifier', 'porta — porte d’une ville', 'puella — jeune fille', 'puer — garçon', 'urbs — ville', 'viātor — voyageur', 'vocāre — appeler']),
